            await settime(pg, 0, 12); await pg.evaluate("$('#wtBg').value='#1e40af';$('#wtBg').dispatchEvent(new Event('input'))")
            await pg.click('#wbShow'); await pg.wait_for_timeout(350)
            s = await pg.evaluate(PV)
